"""Consume a kept composition into the common native-symbol Part store.

The temporary derivation supplies argument order. Neither that derivation nor
a working identity is retained on an LTM0 occurrence.
"""
import torch

from ClauseRow import Composition
from Layers import assert_cube
from Spaces import _concept_alloc_of


class PartClosing:
    # These operations assert a relation between concepts. A description
    # fold or a determiner introduction does not itself require identities
    # for its operands; it retains a pair only when both already have them.
    _relations = frozenset(('lift', 'part', 'assertPart', 'whole', 'implies', 'equal', 'verb'))

    def __init__(self, owner, store):
        self.owner, self.store = owner, store
        self.alloc = _concept_alloc_of(owner)
        self.parts = self.alloc.parts
        self.symbols = {}
        self.edges = []
        self._terms = {}
        self._plan = []
        self._planned = {}
        self._pairs = {}
        self._definitions = {}
        self._word_origins = {}
        self._occupations = []
        self._next = int(self.alloc.next_id)
        self._ready = False
        self._committed = False
        self._seated = set()
        self.when = None

    def _point(self, symbol):
        if symbol is None:
            return None
        row = self.owner._csw_row_of(int(symbol))
        return None if row is None else self.owner.similarity_codebook.lookup_rows(row).detach()

    @torch.no_grad()
    def _seat(self, symbol, term, types=()):
        if symbol in self._seated:
            return symbol
        self.alloc.symbol_types.setdefault(int(symbol), set()).update(types)
        self.alloc.symbol_types[int(symbol)].add('concept')
        self.alloc.reference_orders.setdefault(int(symbol), int(term.order))
        row = self.owner._csw_row_of(int(symbol))
        if row is None:
            self.owner._preflight_concept_row(int(term.order))
            row = self.owner._csw_concept_row(int(term.order), int(symbol))
        if row is None:
            raise RuntimeError('a closing symbol has no native conceptual seat')
        point = assert_cube(term.point.detach())
        bank = self.owner.similarity_codebook
        if point.shape != bank.W[row].shape:
            raise ValueError('a minted composing argument requires its full concept-space value')
        bank.W[row].copy_(point.to(bank.W))
        self.alloc.settle(int(symbol))
        self._seated.add(symbol)
        return int(symbol)

    def _native(self, reference):
        reference = int(reference)
        return reference > 0 and reference in self.alloc.placement and reference not in self.alloc.retired

    def _reserve(self):
        symbol = self._next
        self._next += 1
        return symbol

    def _plan_term(self, value, as_argument):
        pending, active = [(value, as_argument, False)], set()
        while pending:
            term, argument, ready = pending.pop()
            if id(term) in self._planned:
                self._plan_one(term, argument)
                continue
            if ready:
                active.remove(id(term))
                self._plan_one(term, argument)
                continue
            if id(term) in active:
                raise ValueError('recursive composing object')
            active.add(id(term))
            pending.append((term, argument, True))
            dependencies = [(child, term.operation in self._relations) for child in term.children]
            if term.binding is not None:
                dependencies.append((term.binding, True))
            pending.extend((child, needed, False) for child, needed in reversed(dependencies))
        return self._planned[id(value)]['symbol']

    def _plan_one(self, value, as_argument):
        if id(value) in self._planned:
            record = self._planned[id(value)]
            if record.get('alias') is not None:
                record['symbol'] = self._plan_term(record['alias'], as_argument)
                record['types'] = self._planned[id(record['alias'])]['types']
                return record['symbol']
            if value.formal_name == 'lower' and len(value.children) == 2:
                head = value.children[value.head_role - 1]
                record['symbol'] = self._plan_term(head, as_argument)
                record['types'] = self._planned[id(head)]['types']
                return record['symbol']
            if as_argument and record['symbol'] is None:
                record['symbol'] = self._reserve()
            record['seat'] |= (as_argument and value.binding is None
                               and record['symbol'] is not None and not self._native(record['symbol'])
                               and self._point(record['symbol']) is None)
            return record['symbol']
        if (value.operation == 'bind' and len(value.children) == 1
                and value.binding is None and value.reference in (-1, 0)):
            child = value.children[0]
            if value.order == child.order and torch.equal(value.point, child.point):
                # A dummy preserves the carried reference even when its
                # working content is the lexical row rather than that bank row.
                symbol = self._plan_term(child, as_argument)
                held = self._planned[id(child)]
                record = dict(value=value, symbol=symbol, edge=held['edge'], pair=held['pair'],
                    types=held['types'], seat=False, alias=child)
                self._planned[id(value)] = record
                self._plan.append(record)
                return symbol
        children = tuple(self._plan_term(child, value.operation in self._relations)
                         for child in value.children)
        reference = (self._plan_term(value.binding, True) if value.binding is not None else
                     value.reference if self._native(value.reference) else None)
        edge, pair, types = None, None, ('object',)
        if not children:
            if reference is None:
                location = self.store.location(value.reference)
                if isinstance(location, int):
                    reference = self.owner.components.reference_close._derivation_symbol(
                        self.store.occurrence_of(location))
            if (reference is None and value.reference > 0
                    and self.store.location(value.reference) is None):
                raise ValueError('a closing argument names an unavailable native reference')
            if reference is None and as_argument:
                reference = self._reserve()
        elif len(children) == 1:
            # A unary face changes the working concept/order. It supplies no
            # ordered pair; any encompassing binary operation mints that value
            # when it actually needs a distinct argument.
            if reference is None and as_argument:
                child = self._point(children[0])
                if child is not None and torch.equal(child.to(value.point), value.point):
                    reference = children[0]
                else:
                    reference = self._reserve()
                types = ('kind',) if value.order > 1 else ('object',)
            child_record = self._planned[id(value.children[0])]
            edge, pair = child_record['edge'], child_record['pair']
        elif len(children) == 2:
            if value.formal_name == 'lower':
                head = value.children[value.head_role - 1]
                if not torch.equal(value.point, head.point):
                    raise ValueError('inline lowering must preserve its description exactly')
                reference = self._plan_term(head, as_argument)
                record = dict(value=value, symbol=reference, edge=None, pair=None,
                              types=self._planned[id(head)]['types'], seat=False)
                self._planned[id(value)] = record
                self._plan.append(record)
                return reference
            part, whole = children
            if value.operation == 'whole':
                part, whole = whole, part
            # The pair retains the derivation. Its result needs a bank seat
            # only if a containing relation uses that result as an argument.
            if part is not None and whole is not None:
                pair = (part, whole)
                edge = self._pairs.get(pair, self.parts.find(*pair))
                if edge is None:
                    edge = self._reserve()
                    self._pairs[pair] = edge
            types = ('situation',) if value.operation in (
                'lift', 'part', 'assertPart', 'whole', 'implies', 'equal') else ('object',)
            if value.operation == 'verb':
                types = (*types, 'state')
                child_types = set(self.alloc.symbol_types.get(children[1], ()))
                for child_record in self._plan:
                    if child_record['symbol'] == children[1]:
                        child_types.update(child_record['types'])
                if 'situation' in child_types:
                    types = (*types, 'speech_individual')
            if reference is None:
                reference = edge
                if reference is None and as_argument:
                    reference = self._reserve()
        else:
            raise ValueError('a composition has one or two arguments')
        record = dict(value=value, symbol=reference, edge=edge, pair=pair, types=types,
                      seat=as_argument and value.binding is None and reference is not None
                      and not self._native(reference)
                      and self._point(reference) is None)
        self._planned[id(value)] = record
        self._plan.append(record)
        return reference

    def _definition(self, symbol, word, evidence, *, marker=False):
        if marker or symbol is None or not self._native(word) or word == symbol:
            return
        if ('word' in self.alloc.symbol_types.get(symbol, ())
                or symbol in self.owner.definitions.word_ids):
            return
        interpreter = getattr(self.owner, 'interpret', None)
        description = self.alloc.word_descriptions.get(word)
        if description is None and interpreter is not None:
            description = interpreter._pending.get(word)
        if description is None:
            raise ValueError('a word-derived mint requires its admitted word description')
        pair = symbol, word
        edge = self._pairs.get(pair, self.parts.find(*pair))
        if edge is None:
            edge = self._reserve()
            self._pairs[pair] = edge
        self._definitions[pair] = edge, description, evidence

    def _word_origin(self, value):
        # Surface/form attachments keep their head's lexical use. If that
        # phrase is minted as a relation argument, its definition belongs to
        # the minted phrase even while the description remains unminted.
        while (value.word_id < 0 and value.children and value.head_role
               and value.operation not in self._relations):
            value = value.children[value.head_role-1]
        return value.word_id

    def prepare(self, clause):
        term = self._terms.setdefault(id(clause), self.clause_term(clause))
        pending, visited = [term], set()
        width = self.owner.similarity_codebook.W.shape[-1]
        while pending:
            value = pending.pop()
            if id(value) in visited:
                continue
            visited.add(id(value))
            if value.point.shape != (width,):
                raise ValueError('closing arguments require the full concept-space width')
            assert_cube(value.point)
            pending.extend(value.children)
        # A determiner's new referent is a working concept, then an LTM0
        # occurrence. Only use as a relation argument requires minting here;
        # recurrence promotion belongs to the later occurrence owner.
        self._plan_term(term, False)
        # Follow derivation order, never the process-dependent ordering of
        # Python object IDs, when assigning the native definition handles.
        for record in self._plan:
            value = record['value']
            if id(value) in visited:
                word = self._word_origin(value)
                if self._native(word):
                    self._word_origins[id(value)] = word, clause.evidence
        if clause.minted or bool(clause.reference_request and
                                 clause.reference_request.get('mode') == 'mint'):
            if self._native(clause.subject_word_id):
                self._word_origins[id(term)] = int(clause.subject_word_id), clause.evidence

    def preflight(self):
        # A surface argument contributes form, not a noun definition. The
        # kept plan supplies this position even when the word has an object.
        markers = set()
        pending = [record['value'].children[0] for record in self._plan
                   if record['value'].operation == 'surface'
                   and len(record['value'].children) == 2]
        while pending:
            term = pending.pop()
            if id(term) not in markers:
                markers.add(id(term))
                pending.extend(term.children)
        for term, (word, evidence) in self._word_origins.items():
            record = self._planned[term]
            if record['seat'] or self._point(record['symbol']) is not None:
                self._definition(record['symbol'], word, evidence, marker=term in markers)
        ref = self.store.__dict__.get('_occupation_owner')
        occupations = None if ref is None else ref()
        for record in self._plan:
            value = record['value']
            # Only an admitted formal operation supplies distributional
            # occupations. A direct semantic pair invents no grammar role.
            name = value.formal_name
            if name is None or occupations is None:
                continue
            for role, child in enumerate(value.children, 1):
                symbol = self._planned[id(child)]['symbol']
                if symbol is not None and (symbol != child.word_id or name == 'lower'):
                    argument = f'{name}_argin{role}'
                    if argument not in occupations.index:
                        raise ValueError(f'undeclared closing occupation: {argument}')
                    self._occupations.append((symbol, argument))
            if record['symbol'] is not None:
                argument = f'{name}_argout1'
                if argument in occupations.index:
                    self._occupations.append((record['symbol'], argument))
        new_edges = set(self._pairs.values())
        seats = {record['symbol'] for record in self._plan if record['seat']}
        count = self._next - int(self.alloc.next_id) - len(new_edges - seats)
        if self._next > self.parts.capacity:
            raise OverflowError('LTM2 symbol capacity exhausted before closing')
        self.owner._preflight_concept_allocation(count, context='complete Part closing')
        # Reserve physical seats together. A collection of individually
        # possible admissions must not leave a prefix when their pool fills.
        layer, caps = self.alloc.layer(), self.owner._order_caps()
        occupied = set(layer._tensor_row_keys)
        planned = set()
        for record in self._plan:
            symbol, order = record['symbol'], int(record['value'].order)
            if not record['seat'] or symbol in planned:
                continue
            planned.add(symbol)
            if getattr(self.owner, '_concept_binding', 'mixing') == 'aligned':
                bases = ((0, int(self.owner.nVectors)),)
            elif order == 0:
                bases = ((0, caps[0]), (sum(caps), int(self.owner.nVectors)-sum(caps)))
            else:
                rung = min(order, len(caps)-1)
                bases = ((sum(caps[:rung]), caps[rung]),)
            seat = next((base+i for base, size in bases for i in range(size)
                         if base+i not in occupied), None)
            if seat is None:
                raise RuntimeError(
                    f'complete Part closing exceeds a concept row pool: order={order}, '
                    f'pools={bases}, occupied={len(occupied)}, planned={len(planned)}')
            occupied.add(seat)
        self._ready = True

    @torch.no_grad()
    def _commit(self):
        if not self._ready:
            raise RuntimeError('Part closing must preflight its complete derivation')
        if self._committed:
            return
        # Allocate handles in the order planned, before seating any content.
        start = int(self.alloc.next_id)
        for expected in range(start, self._next):
            if self.alloc.new_concept() != expected:
                raise RuntimeError('native symbol allocation changed during closing')
        for record in self._plan:
            value, symbol, edge = record['value'], record['symbol'], record['edge']
            if record['pair'] is not None and len(value.children) == 2:
                self.parts.add(*record['pair'], symbol=edge, when=self.when)
                self.edges.append(edge)
                self.alloc.symbol_types.setdefault(edge, set()).update(record['types'])
                if value.operation == 'equal':
                    # Equality constructs membership in a singleton. The
                    # argument's type supplies that reading on later access.
                    self.alloc.singletons.add(record['pair'][1])
            if record['seat']:
                self._seat(symbol, value, record['types'])
            self.symbols[id(value)] = symbol
        for (symbol, word), (edge, description, evidence) in self._definitions.items():
            self.alloc.symbol_types.setdefault(symbol, set()).add('object')
            self.alloc.symbol_types.setdefault(word, set()).add('word')
            self.alloc.word_descriptions[word] = description
            self.parts.add(symbol, word, symbol=edge, when=self.when,
                           truth_plus=evidence[0], truth_minus=evidence[1], witness=False)
            self.owner.definitions.add(edge)
            interpreter = self.owner.interpret
            interpreter._pending.pop(word, None)
            interpreter._field_pending.discard(word)
        ref = self.store.__dict__.get('_occupation_owner')
        occupations = None if ref is None else ref()
        if occupations is not None:
            for symbol, argument in self._occupations:
                occupations.add(symbol, argument)
        self._committed = True

    def clause_term(self, clause):
        if clause.composition is not None:
            return clause.composition
        # Direct callers supply their already-completed operands. They do not
        # get a fabricated derivation of an absolute point.
        if clause.relation is None:
            reference = clause.refs[0]
            return Composition(clause.point, order=clause.order,
                               reference=reference if type(reference) is int else -1)
        terms = []
        for role in (0, 2):
            ref = clause.refs[role]
            if isinstance(ref, tuple):
                terms.append(self.clause_term(clause.children[ref[1]]))
            else:
                point = self._point(ref) if self._native(ref) else clause.meaning.roles[role]
                terms.append(Composition(point, reference=ref, order=clause.order))
        # Direct relation construction names its resulting native concept by
        # the encompassing argument, exactly the Part operator's point face.
        return Composition(terms[1].point, tuple(terms), operation=clause.relation,
                           order=clause.order)

    def close(self, clause, *, pair=(0., 0.), when=None, surprise=-1.):
        self._commit()
        term = self._terms[id(clause)]
        record = self._planned[id(term)]
        if record['edge'] is not None:
            self.parts.add(*record['pair'], truth_plus=pair[0], truth_minus=pair[1],
                           when=when, surprise=surprise, witness=False)
        return record['edge'] if clause.relation is not None else self.symbols[id(term)]

    Only the two arguments and the six Part columns are durable. The
    grammatical operator in this view is chosen from the argument types.
    """
    symbol = int(symbol)
    part = self.parts.row(symbol)
    owner = self._concept_owner()
    from Spaces import _concept_alloc_of
    alloc = _concept_alloc_of(owner)
    def types(identity):
        result = set(alloc.symbol_types.get(identity, ()))
        if identity in alloc.singletons:
            result.add('singleton')
        if alloc.order_of(identity) > 1:
            result.add('kind')
        return result
    readings = self.parts.readings(symbol, types)
    if reading is None:
        reading = ('implies' if 'conditional' in readings else
                   'equal' if 'equality' in readings else 'part')
    if reading == 'implies' and 'conditional' not in readings:
        raise ValueError('a conditional requires two situation arguments')
    if reading == 'equal' and 'equality' not in readings:
        raise ValueError('equality requires singleton membership')
    left, right = part['refs'].tolist()
    roles = self.slots.new_zeros(3, self.nDim)
    for role, reference in ((0, left), (2, right)):
        value = self._concept_point(reference)
        if value is not None:
            roles[role] = self._fit(value)
    # This is an operation request, not an identity coordinate or a
    # third LTM1 column. It disappears with the read.
    roles[1] = predicate_point(reading, roles[1])
    pair = tuple(float(part[name]) for name in ('truth_plus', 'truth_minus'))
    from ThoughtReferences import with_slots
    meaning = with_slots(ConceptualMeaning(roles,
        torch.ones(3, dtype=torch.bool, device=roles.device),
        role_refs=(('sym', left), ('sym', predicate_identity(reading)), ('sym', right)),
        sentence_kind='relation',
        bindings={'_equality': True} if reading == 'equal' else {}),
        (), pair=pair)
    return dict(part, meaning=meaning, occurrence=('sym', symbol),
        row_id=symbol, refs=part['refs'].clone(), readings=readings,
        evidence=pair, trust=pair[0]-pair[1], source_trust=0.,
        kind='observation' if any(pair) else 'unverified', order=alloc.order_of(symbol),
        stream=(), pending=False,
        metadata_complete=True, expectation=self.expectation_of(('sym', symbol)), text=None)

def location(self, reference):
    """Find either an LTM0 occurrence or a native LTM1 symbol."""
    if isinstance(reference, tuple):
        if len(reference) == 2 and reference[0] == 'sym' and self.parts.contains(reference[1]):
            return reference
        return self._index_occurrences.get(reference)
    row = self.index_of_row(reference)
    return row if row is not None else (('sym', int(reference))
        if self.parts.contains(reference) else None)

def clause_relation(self, field):
    """Infer the row kind from occupancy and its REL's native identity."""
    if field.slots.shape[0] == 1:
        return None
    if field.slots.shape[0] != 3:
        raise ValueError('a completed row occupies one or three slots')
    resolve = getattr(self, '_predicate_kind', None)
    reference = field.refs[1]
    if isinstance(reference, ClausePredicate):
        return predicate_relation(reference.identity)
    result = resolve(reference) if resolve is not None and type(reference) is int else 'operator'
    if result not in ('part', 'implies', 'operator'):
        raise ValueError('the REL identity has an unknown grammatical kind')
    return result

@contextmanager
def clause_assertions(self, *, trust, origin, text):
    """External TruthSet authority, scoped to completed outer clauses only."""
    previous = self.__dict__.get('_clause_assertion')
    context = dict(trust=float(trust), origin=origin, text=text, rows=[])
    object.__setattr__(self, '_clause_assertion', context)
    try:
        yield context['rows']
    finally:
        object.__setattr__(self, '_clause_assertion', previous)

def _native_reference_indexes(self):
    """Derived identity-to-occurrence caches, invalidated by row edits."""
    count = len(self)
    token = (count, id(self.row_ids), self.row_ids._version)
    if self.__dict__.get('_native_reference_token') != token:
        rows = {}
        for row, identity in enumerate(self.row_ids[:count].tolist()):
            if identity not in (-1, 0):
                rows.setdefault(identity, row)
        object.__setattr__(self, '_native_row_index', rows)
        object.__setattr__(self, '_native_reference_token', token)
    return self._native_row_index

def index_of_row(self, reference):
    return self._native_reference_indexes().get(int(reference))

def _index_slot_metadata(self, address):
    from Occurrence import slot_key
    data = dict(self._semantic_rows.get(address, {}).get('bindings', ()))
    for kind, role in (*data.get('_open_references', ()), *data.get('_bound_roles', ())):
        if kind != 'referent':
            continue
        identity = slot_key(address, role)
        previous = self._slot_index.get(identity)
        if previous is not None and previous != (address, role):
            raise RuntimeError('64-bit slot collision; refusing to merge different slots')
        self._slot_index[identity] = address, role

def slot_of_reference(self, reference):
    """Derived shared posting: source address and role remain authoritative."""
    if self.__dict__.get('_slot_index_source') is not self._semantic_rows:
        self._slot_index_source, self._slot_index = self._semantic_rows, {}
        for address in self._semantic_rows:
            self._index_slot_metadata(address)
    value = self._slot_index.get(int(reference))
    if value is None:
        return None
    address, role = value
    row = self._index_occurrences.get(address)
    if row is None:
        return None
    if self.index_of_row(reference) is not None:
        raise RuntimeError('slot address collides with an occurrence')
    return row, role

def semantic_reference(self, reference):
    slot = self.slot_of_reference(reference)
    if slot is not None:
        return ('slot', self.occurrence_of(slot[0]), slot[1])
    row = self.index_of_row(reference)
    return self.occurrence_of(row) if row is not None else ('sym', reference)

def point_of_row(self, reference):
    """Read a concept/idea point; a relation explicitly has no point."""
    slot = self.slot_of_reference(reference)
    if slot is not None:
        return self.slots[slot]
    index = self.index_of_row(reference)
    if index is not None:
        return self.slots[index, 0] if int(self.role_mask[index].sum()) == 1 else None
    resolve = getattr(self, '_concept_point', None)
    if resolve is None:
        raise ValueError('shared concept index is not attached')
    point = resolve(int(reference))
    if point is None:
        raise ValueError(f'unavailable shared row {reference}')
    return self._fit(point)

def _clause_reference(self, reference, children):
    if isinstance(reference, ClausePredicate):
        return reference.identity
    return int(self.row_ids[children[reference[1]]]) if isinstance(reference, tuple) else reference

@torch.no_grad()
def write_clause(self, clause, *, trust=None, origin=None, stream=-1, kind='observation',
                evidence=None, text=None, expectation=None, document_key=None,
                sentence_index=0, content_key=None, written_rows=None):
    """Close concepts into LTM0 and the derivation's argument pairs into LTM1.

    Wide working identities are never stored on occurrence rows. A completed
    relative field keeps its occurrence beside its native Part symbol and
    returns the symbol; an absolute or still-open field returns its occurrence.
    Both have the common row/read interface.
    """
    import math
    from PartClosing import PartClosing
    from ThoughtReferences import bindings, open_slots, with_slots
    if not isinstance(clause, Clause):
        raise TypeError('write_clause requires a completed field')
    if document_key is not None:
        from Occurrence import native_content_key
        with self.at_address(document_key, sentence_index,
                             content_key or native_content_key(clause.meaning)):
            return self.write_clause(clause, trust=trust, origin=origin, stream=stream,
                kind=kind, evidence=evidence, text=text, expectation=expectation,
                written_rows=written_rows)
    authority = self.__dict__.get('_clause_assertion')
    if authority is not None:
        if clause.meaning.mode == 'interrogative':
            raise ValueError('a TruthSet cannot assert an interrogative clause')
        trust, origin, text = authority['trust'], authority['origin'], authority['text']
        kind = 'fact'
    if trust is not None and not math.isfinite(float(trust)):
        raise ValueError('clause provenance must be finite')
    if kind not in self.KINDS or type(stream) is not int or stream < -1:
        raise ValueError('invalid clause evidence kind or stream')
    if text is not None and not isinstance(text, str):
        raise ValueError('truth source text must be a string')
    owner = self.__dict__.get('_concept_owner')
    if owner is None or owner() is None:
        raise ValueError('clause admission requires its native concept owner')
    closing = PartClosing(owner(), self)
    context = self.__dict__.get('_write_address')
    nodes, visiting, visited = [], set(), set()
    def visit(value):
        if id(value) in visiting:
            raise ValueError('a temporary derivation cannot contain an object cycle')
        if id(value) in visited:
            return
        visiting.add(id(value))
        for child in value.children:
            visit(child)
        visiting.remove(id(value)); visited.add(id(value)); nodes.append(value)
        for companion in value.companions:
            visit(companion)
    visit(clause)
    pairs, edge_pairs, addresses, prepared, required = {}, {}, {}, set(), 0
    prediction = None if expectation is None else expectation.estimate
    surprise = -1. if prediction is None else expectation.surprise_for(clause.meaning)
    sources = () if expectation is None else tuple(expectation.source_occurrences)
    estimate, observation_marks = None, {}
    if prediction is not None:
        if expectation.identities is not None:
            observation_marks['_symbol_handles'] = tuple(expectation.identities.cpu().tolist())
        activation = expectation.activation
        if activation is None:
            activation = expectation.residual + prediction.expected_activation
        observation_marks['_observed_symbol_activations'] = tuple(
            (int(identity), tuple(pair)) for identity, pair in zip(
                prediction.symbol_ids.cpu().tolist(), activation.detach().cpu().tolist()))
        observation_marks.update({key: value for key, value in bindings(clause.meaning).items()
                                  if key == '_withheld_symbols'})
        if sources:
            if any(self.location(source) is None for source in sources):
                raise ValueError('estimate source occurrence is unavailable')
            retained = prediction.retained_bindings(observed=expectation.observed,
                occupied=expectation.occupied, activation=activation,
                identities=expectation.identities)
            # The predictor's frozen activation target is an audit of
            # the arrival, not another stored working identity or an
            # extra column on a Part edge.
            retained['_expectation_observation'] = observation_marks
            estimate = ConceptualMeaning(prediction.roles,
                torch.ones(3, dtype=torch.bool, device=prediction.roles.device),
                mode='unspecified', bindings=retained, scope=prediction.scope)
            self._validate_local_references(estimate)
            self._normalise_expectation_provenance(dict(kind='estimate',
                source_occurrences=sources, intended_occurrence=None,
                presence_logits=tuple(prediction.presence_logits.detach().cpu().tolist()),
                stream=expectation.stream, document=expectation.document), self.address_domain)
            previous = self._address_for_write(estimate, kind='estimate',
                **self._estimate_write_address(estimate, document=expectation.document,
                                              stream=expectation.stream))[-1]
            required += previous is None
    def pending(value):
        return any(tag != 'evidence' for tag, _ in
            bindings(value.meaning).get('_open_references', ())) or (value.relation is not None
            and any(value.refs[role] in (-1, 0) for role in (0, 2)))
    def incomplete(value):
        return pending(value) or any(incomplete(child) for child in value.children)
    def row_kind(value):
        if value is clause or value in clause.companions:
            return kind
        declared = bindings(value.meaning).get('_open_references', ())
        return 'question' if set(declared).intersection(open_slots(value.meaning)) else 'unverified'
    def retained_pair(value):
        term = closing._terms.get(id(value))
        return (value.relation is not None and term is not None
            and closing._planned[id(term)]['edge'] is not None)
    for position, value in enumerate(nodes):
        asserted = value is clause or value in clause.companions
        pair = tuple(map(float, value.evidence if evidence is None or not asserted else evidence))
        from_trust = asserted and (authority is not None or (trust is not None and evidence is None))
        if from_trust:
            signed = max(-1., min(1., float(trust)))
            pair = (max(signed, 0.), max(-signed, 0.))
        if len(pair) != 2 or any(not math.isfinite(x) or not 0 <= x <= 1 for x in pair):
            raise ValueError('clause evidence requires two finite poles in [0, 1]')
        pairs[id(value)] = pair
        # Occurrences retain polarity as a field; the Part edge has
        # no polarity column and needs canonical evidence poles.
        edge_pairs[id(value)] = pair[::-1] if from_trust and not value.meaning.polarity else pair
        if not incomplete(value):
            closing.prepare(value)
            prepared.add(id(value))
        from Occurrence import native_content_key
        kwargs = ({} if value is clause and context is not None else
            dict(document_key=('direct', kind) if context is None else
                 ('embedded', context[0], context[1]), sentence_index=position,
                 content_key=native_content_key(value.meaning)))
        previous = self._address_for_write(value.meaning,
            kind=row_kind(value), **kwargs)[-1]
        required += previous is None
        addresses[id(value)] = kwargs
    if len(self) + required > self.capacity:
        raise OverflowError('LTM1 capacity exhausted before clause admission')
    closing.preflight()
    from RowTime import stamp
    closing.when = stamp(self)
    rows = {}
    estimate_index = None
    if estimate is not None:
        estimate_index = self.append_estimate(estimate,
            presence_logits=prediction.presence_logits, source_occurrences=sources,
            stream=expectation.stream, document=expectation.document)
    for value in nodes:
        asserted = value is clause or value in clause.companions
        pair = pairs[id(value)]
        if id(value) in prepared:
            symbol = closing.close(value, pair=edge_pairs[id(value)], when=closing.when,
                                   surprise=surprise if asserted else -1.)
        else:
            symbol = None
        if retained_pair(value):
            if symbol is None or not self.parts.contains(symbol):
                raise RuntimeError('a completed relation did not produce a Part edge')
        retain_open = pending(value) or (value.relation is not None and incomplete(value))
        if retain_open:
            # An open question is retained at the existing occurrence
            # boundary. Filling it later changes only its working read.
            named = []
            for role, reference in enumerate(value.refs):
                if isinstance(reference, ClausePredicate):
                    reference = ('sym', reference.identity)
                elif isinstance(reference, tuple) and reference[:1] == ('clause',):
                    child = value.children[reference[1]]
                    term = closing._terms.get(id(child))
                    symbol = None if term is None else closing.symbols.get(id(term))
                    reference = (('sym', symbol) if symbol is not None
                        and closing._point(symbol) is not None else
                        self.occurrence_of(rows[id(child)]))
                elif type(reference) is int and reference not in (-1, 0):
                    reference = self.semantic_reference(reference)
                else:
                    reference = value.meaning.role_refs[role]
                named.append(reference)

"""Equality substitution over the rows already read by an episode.

There is no store, vocabulary or operation evaluator here. A proof uses
native identities, the two cached operands of an ended point, or the three
roles of a relative row, and positive equalities in checked serial results.
"""
from dataclasses import replace

from ThoughtReferences import bindings, evidence_pair, fill, open_slots, with_slots


def equality(meaning):
    return bool(bindings(meaning).get('_equality'))


def integrate(goal, result, previous):
    if not equality(goal):
        return None
    frames = result.evidence.get('frames', ())
    if not frames:
        return goal
    terms, edges = {}, {}
    for item in (*previous, result):
        terms.update(item.evidence.get('components', {}))
    for item in previous:
        values = item.evidence.get('frames', ())
        returned = item.evidence.get('returned_meaning')
        if returned is not None and equality(returned):
            values = (*values, dict(meaning=returned, evidence=evidence_pair(returned),
                occurrence=item.evidence.get('derivation_witness'),
                witnesses=bindings(returned).get('_thought_witnesses', ())))
        for frame in values:
            meaning = frame['meaning']
            if not equality(meaning) or frame['evidence'][0] <= 0:
                continue
            a, b = meaning.role_refs[0], meaning.role_refs[2]
            witness = frame.get('occurrence')
            proof = (witness,) if witness is not None else tuple(frame.get('witnesses', ()))
            for left, right in ((a, b), (b, a)):
                if left is not None and right is not None:
                    edges.setdefault(left, []).append((right, proof, frame['evidence'][0]))

    def equivalent(left, right, visiting=frozenset()):
        if left is None or right is None:
            return None
        if left == right:
            return (), 1.
        key = left, right
        if key in visiting or len(visiting) >= 64:
            return None
        visiting = visiting | {key}
        for other, witnesses, support in edges.get(left, ()):
            found = equivalent(other, right, visiting)
            if found is not None:
                return (*witnesses, *found[0]), min(support, found[1])
        a, b = terms.get(left), terms.get(right)
        for term, own, other in ((a, left, right), (b, right, left)):
            if term is not None and term.get('reference') not in (None, own):
                found = equivalent(term['reference'], other, visiting)
                if found is not None:
                    return found
        if a is None or b is None or a['kind'] != b['kind']:
            return None
        operands_a, operands_b = a['operands'], b['operands']
        if not operands_a or len(operands_a) != len(operands_b):
            return None
        proof, strength = (), 1.
        for first, second in zip(operands_a, operands_b):
            found = equivalent(first, second, visiting)
            if found is None:
                return None
            proof, strength = (*proof, *found[0]), min(strength, found[1])
        return proof, strength

    free = [role for kind, role in open_slots(goal) if kind == 'referent']
    bound = [role for kind, role in bindings(goal).get('_bound_roles', ()) if kind == 'referent']
    roles = free or bound
    if len(roles) != 1 or roles[0] not in (0, 2):
        return goal
    target = roles[0]
    # An initial match supplies the free variable opposite the fixed
    # operand. Subsequent selected matches rewrite that variable's region.
    region = goal.role_refs[2-target] if free else goal.role_refs[target]
    for frame in frames:
        meaning = frame['meaning']
        if not equality(meaning) or frame['evidence'][0] <= 0:
            continue
        for source, answer in ((0, 2), (2, 0)):
            found = equivalent(region, meaning.role_refs[source])
            if found is None or meaning.role_refs[answer] is None:
                continue
            if not free and meaning.role_refs[answer] == goal.role_refs[2-target]:
                continue  # The defining premise read backwards makes no progress.
            proof, support = found
            witnesses = tuple(dict.fromkeys((*bindings(goal).get('_thought_witnesses', ()),
                                             *proof, frame['occurrence'])))
            refs = list(goal.role_refs)
            refs[target] = None
            opened = with_slots(replace(goal, role_refs=tuple(refs)), (('referent', target),))
            value = fill(opened, dict(reference=meaning.role_refs[answer],
                binding_value=meaning.roles[answer], support_true=min(support, frame['evidence'][0]),
                support_false=min(support, frame['evidence'][1])), witnesses=witnesses, operation='query')
            data = bindings(value)
            data['_derived_binding'] = not bool(free)
            data['_direct_binding'] = bool(free)
            # A derived chain's support is its weakest link, never the max
            # accumulated by independent direct witnesses of one region.
            if not free:
                support = min(evidence_pair(goal)[0], support)
                value = with_slots(value, (), pair=(min(support, frame['evidence'][0]),
                                                    min(support, frame['evidence'][1])))
            return replace(value, bindings=dict(bindings(value), **{
                key: data[key] for key in ('_derived_binding', '_direct_binding')}))
    return goal

    sources = []
    # Familiarity is summed support, not a retrieved row or a maximum.
    # Only facts certify truth; observations can be retrieved by what.
    for record in result['value']:
        if record['kind'] != 'fact':
            continue
        # Preserve the evidence source without retaining an LTM frame.
        # Only what may expose a stored meaning to serial context.
        sources.append({key: record[key] for key in
                        ('occurrence', 'origin', 'text', 'trust', 'match')})
        # Existence uses external event authority. The separate ended
        # identification pair is exposed by true, never used as trust.
        signed = float(record['trust'])
        if record['meaning'].polarity != description.polarity:
            signed = -signed
        positive += record['match'] * max(0., signed)
        negative += record['match'] * max(0., -signed)
    return {'support_true': min(1., positive), 'support_false': min(1., negative),
            'familiarity': positive + negative, 'meaning': description.detached(),
            'candidates': tuple(sources),
            'records_scanned': result['records_scanned'], 'incomplete': result['incomplete']}

def end_evidence(self, reference, *, max_records, work):
    """Read the two poles of one addressed ended clause, under the same bound."""
    store = object.__getattribute__(self, '_ThoughtLTMCapability__store')()
    from Layers import LTM0
    if not isinstance(store, LTM0) or store.location(reference) is None:
        raise ValueError('ended clause occurrence is unavailable')
    if not max_records:
        raise ValueError('ended clause is unavailable within the query read limit')
    work.require('record')
    index = store.location(reference)
    retained = store.row(index)
    meaning = retained['meaning']
    if meaning is None:
        raise ValueError('ended clause metadata is unavailable')
    positive, negative = retained['evidence']
    if retained['kind'] == 'estimate':
        positive = negative = 0.
    return dict(value=meaning, support_true=positive, support_false=negative, meaning=meaning,
                occurrence=reference, witnesses=(reference,), trust=retained['trust'],
                records_scanned=1, incomplete=())

def best_match(self, pattern, *, max_records, work, references=()):
    """One best matching row, with its poles and its own occurrence witness."""
    from ThoughtReferences import bindings, open_slots
    data = bindings(pattern)
    relation = data.get('_query_relation')
    if relation == 'truth':
        return self.premise_evidence(pattern.role_refs[0], max_records=max_records, work=work)
    if relation is not None:
        result = self.relation_evidence(relation, pattern.role_refs[0],
            pattern.role_refs[2], max_records=max_records, work=work, excluded=data.get('_query_exclude', ()))
        if data.get('_query_components'):
            result = self._with_components(result, max_records=max_records, work=work)
        return result
    mask = pattern.role_mask.clone()
    for _kind, role in open_slots(pattern):
        mask[role] = False
    if not bool(mask.any()):
        # A lone unfilled name supplies no retained role to match. A
        # primed row is not evidence for an unconstrained wildcard;
        # selecting an antecedent belongs to bind's location menu.
        return dict(value=(), frames=(), result_kind='set', support_true=0.,
            support_false=0., witnesses=(), records_scanned=0, incomplete=())
    clean = replace(pattern, bindings={key: value for key, value in data.items()
                                       if not key.startswith('_')})
    found = self._cued(clean, max_records=max_records, work=work, references=references,
                       role_mask=mask)
    tau = object.__getattribute__(self, '_ThoughtLTMCapability__tau')
    excluded = set(data.get('_query_exclude', ()))
    if data.get('_query_occurrence') is not None:
        excluded.add(data['_query_occurrence'])
    candidates = tuple(row for row in found['value']
                       if row['match'] >= tau and row['kind'] != 'estimate'
                       and (row['kind'] != 'question' or tuple(row['evidence']) != (0., 0.))
                       and row['occurrence'] not in excluded)
    best = max(candidates, key=lambda row: row['match']) if candidates else None
    frames = () if best is None else (best,)
    positive, negative = (0., 0.) if best is None else best['evidence']
    if best is not None and best['meaning'].polarity != pattern.polarity:
        positive, negative = negative, positive
    return dict(value=frames, frames=frames, result_kind='set',
                support_true=positive, support_false=negative,
                witnesses=() if best is None else (best['occurrence'],),
                records_scanned=found['records_scanned'], incomplete=found['incomplete'])

def _with_components(self, result, *, max_records, work):
    """Read the typed Part expression under the existing work meter."""
    store = object.__getattribute__(self, '_ThoughtLTMCapability__store')()
    from PartRead import expression_components
    components, scanned, missing = expression_components(store,
        [frame['occurrence'] for frame in result.get('frames', ())],
        max_records=max_records, work=work, scanned=result.get('records_scanned', 0))
    incomplete = (*result.get('incomplete', ()), *missing)
    return dict(result, components=components, records_scanned=scanned,
                incomplete=tuple(dict.fromkeys(incomplete)))

def truth_evidence(self, description, *, max_records, work):
    result = self.best_match(description, max_records=max_records, work=work)
    if result['frames']:
        result['trust'] = result['frames'][0]['trust']
    return result

def premise_evidence(self, reference, *, max_records, work):
    """A proposition's two poles and witnessing occurrence, under the meter."""
    from ThoughtFaces import pair
    store = object.__getattribute__(self, '_ThoughtLTMCapability__store')()
    if store is None:
        return pair(frames=(), records_scanned=0)
    if reference and store.location(reference) is not None:
        found = self.end_evidence(reference, max_records=max_records, work=work)
        row = store.row(store.location(reference))
        return dict(found, frames=(row,))
    scanned, best = 0, None
    for index in range(min(len(store), max_records)):
        if not work.consume('record'):
            break
        scanned += 1
        row = store.row(index)
        meaning = row['meaning']
        if row['kind'] in ('question','estimate','unverified') or meaning is None:
            continue
        if int(meaning.role_mask.sum()) != 1:
            continue
        ref = meaning.role_refs[0]
        if ref == reference and (best is None or max(row['evidence']) > max(best['evidence'])):
            best = row
    if best is None:
        return pair(frames=(), records_scanned=scanned)
    return pair(best['meaning'], *best['evidence'], meaning=best['meaning'],
        frames=(best,), witnesses=(best['occurrence'],), records_scanned=scanned)

def relation_evidence(self, relation, left, right, *, max_records, work, excluded=()):
    """Read Part witnesses; argument types determine permissible readings."""
    from ThoughtFaces import pair
    store = object.__getattribute__(self, '_ThoughtLTMCapability__store')()
    if store is None:
        return pair(frames=(), incomplete=('unavailable_ltm',), records_scanned=0)
    if relation not in ('part', 'equal', 'implies'):
        raise ValueError('unknown symbolic relation reading')
    candidates, scanned, incomplete = [], 0, []
    for symbol in store.parts.indices().tolist():
        if scanned >= max_records or not work.consume('record'):
            incomplete.append('work_budget' if work.remaining == 0 else 'capture_limit')
            break
        scanned += 1
        row = store.part_row(symbol)
        if row['occurrence'] in excluded or not any(row['evidence']):
            continue
        if relation == 'equal' and 'equality' not in row['readings']:
            continue
        if relation == 'implies' and 'conditional' not in row['readings']:
            continue
        row = store.part_row(symbol, reading=relation)
        refs = row['meaning'].role_refs
        direct = (left is None or refs[0] == left) and (right is None or refs[2] == right)
        reverse = relation == 'equal' and (left is None or refs[2] == left) and (right is None or refs[0] == right)
        if direct or reverse:
            temporal = ()
            if relation == 'implies' and all(store.parts.contains(ref[1]) for ref in (refs[0], refs[2])):
                # Composed situations have their own retained .when.
                # Read the endpoints on this meter; rule insertion time
                # cannot stand in for their order.
                times = []
                for ref in (refs[0], refs[2]):
                    if scanned >= max_records or not work.consume('record'):
                        incomplete.append('temporal_work_budget')
                        break
                    scanned += 1
                    times.append(store.parts.when[ref[1]])
                if len(times) != 2:
                    continue
                times = torch.stack(times)
                if not bool(times.ne(0).any(-1).all()):
                    incomplete.append('unknown_event_time')
                    continue
                from RowTime import encoder
                onset = encoder().decode_index(times)
                if int(onset[0]) > int(onset[1]):
                    incomplete.append('reversed_event_order')
                    continue
                temporal = (refs[0], refs[2])
            candidates.append(dict(row, temporal_witnesses=temporal, match=1.))
    best = max(candidates, key=lambda row: max(row['evidence'])) if candidates else None
    frames = () if best is None else (best,)
    positive, negative = (0., 0.) if best is None else best['evidence']
    if left == right and left is not None and relation in ('part', 'equal'):
        positive = 1.
    return pair(frames, positive, negative, frames=frames,
                meaning=None if best is None else best['meaning'],
                witnesses=() if best is None else (best['occurrence'], *best.get('temporal_witnesses', ())),
                result_kind='set', records_scanned=scanned, incomplete=tuple(incomplete))

def retrieve(self, question, *, max_records, work, references=()):
    """Return the matching conceptual members and their own evidence.

    Several answers form a temporary whole. Addresses and external trust
    remain provenance; neither replaces a member's conceptual content or
    its ended identification poles.

def fill(meaning, result, *, witnesses=(), operation=None, slots=None):
    """Bind from a checked result, retaining both poles and its provenance."""
    validate_local_references(meaning)
    evidence = result.evidence if hasattr(result, 'evidence') else result
    pair = (float(evidence.get('support_true', 0.)),
            float(evidence.get('support_false', 0.)))
    supplied = evidence.get('meaning')
    if supplied is None:
        frames = evidence.get('frames', ())
        supplied = frames[0].get('meaning') if len(frames) == 1 else None
    if supplied is not None:
        validate_local_references(supplied)
    frames = evidence.get('frames', ())
    roles, mask = meaning.roles.clone(), meaning.role_mask.clone()
    references = list(meaning.role_refs)
    children = list(meaning.constituents)
    rebased = None

    def import_reference(reference):
        nonlocal rebased
        if rebased is None:
            existing = {id(child): index for index, child in enumerate(children)}
            rebased = {}
            for index, child in enumerate(supplied.constituents):
                if id(child) not in existing:
                    existing[id(child)] = len(children)
                    children.append(child)
                rebased[index] = existing[id(child)]
        if isinstance(reference, tuple):
            if reference and reference[0] == 'constituent':
                return ('constituent', rebased[reference[1]])
            return tuple(import_reference(item) for item in reference)
        return reference

    for kind, role in open_slots(meaning):
        if slots is not None and (kind, role) not in slots:
            continue
        if supplied is not None and supplied.role_refs[role] is not None:
            references[role] = import_reference(supplied.role_refs[role])
            roles[role], mask[role] = supplied.roles[role], supplied.role_mask[role]
        elif (supplied is not None and len(frames) == 1
              and bool(supplied.role_mask[role])):
            # A fused one-slot row names itself. It need not pretend its
            # occurrence address is a conceptual-space allocation.
            if int(supplied.role_mask.sum()) == 1:
                references[role] = import_reference(frames[0]['occurrence'])
            roles[role], mask[role] = supplied.roles[role], supplied.role_mask[role]
        elif (evidence.get('reference') is not None
              and torch.is_tensor(evidence.get('binding_value', evidence.get('value')))):
            references[role] = evidence['reference']
            value = evidence.get('binding_value', evidence.get('value')).to(roles)
            width = min(value.shape[-1], roles.shape[-1])
            # An unminted LTM0 candidate can answer only at its retained
            # width. The rest remains the current working request, never a
            # reconstruction of lost occurrence structure.
            roles[role, :width], mask[role] = value[:width], True
    data = bindings(meaning)
    filled_roles = tuple((kind, role) for kind, role in open_slots(meaning)
                         if kind != 'evidence' and references[role] is not None)
    if filled_roles:
        data['_bound_roles'] = tuple(dict.fromkeys((*data.get('_bound_roles', ()), *filled_roles)))
        if '_forward_references' in data:
            data['_forward_references'] = tuple(item for item in data['_forward_references']
                                                 if references[item[0]] is None)
    data['_thought_witnesses'] = tuple(dict.fromkeys((*data.get('_thought_witnesses', ()),
                                                   *witnesses)))
    if operation is not None:
        data['_producing_operation'] = operation
    updated = replace(meaning, roles=roles, role_mask=mask,
                      role_refs=tuple(references), constituents=tuple(children), bindings=data)
    if '_pending' in data:
        data['_pending'] = bool(open_slots(updated))
        updated = replace(updated, bindings=data)
    validate_local_references(updated)
    old = evidence_pair(meaning)
    return with_slots(updated, open_slots(meaning),
                      pair=(max(old[0], pair[0]), max(old[1], pair[1])))


def from_closing(meaning, *, evidence=(0., 0.), unresolved=False):
    """The binder's missing reference, not punctuation, defines questionhood."""
    slots = list(open_slots(meaning))
    if unresolved:
        slots.extend(('relation' if role == 1 else 'referent', role)
                     for role in range(3) if bool(meaning.role_mask[role])
                     and meaning.role_refs[role] is None)
    data = bindings(meaning)
    data['_source_evidence'] = tuple(evidence)
    return with_slots(replace(meaning, bindings=data), slots, pair=evidence)

"""Open references travel with ordinary meanings, never a planner stack."""
from dataclasses import replace
import torch


def bindings(meaning):
    value = meaning.bindings
    if all(isinstance(item, tuple) and len(item) == 2 and isinstance(item[0], str)
           for item in value):
        return dict(value)
    return {'_original_bindings': value} if value else {}


def evidence_pair(meaning):
    return tuple(bindings(meaning).get('_evidence_pair', (0., 0.)))


def open_slots(meaning):
    """An omitted relational operand is open even without an annotation.

    A fused idea has one role. A relational row has three roles, including
    the ones still to be filled; its occupancy is part of the contract.
    Surface mode cannot preserve an already filled reference.
    """
    result = []
    forward_roles = {role for role, _ in bindings(meaning).get('_forward_references', ())}
    for kind, role in bindings(meaning).get('_open_references', ()):
        # Old checkpoints may retain the retired evidence annotation. It
        # denotes ignorance, never a free variable or something bind fills.
        if kind == 'evidence':
            continue
        if kind not in ('referent', 'relation'):
            raise ValueError('unknown open-reference kind')
        if role not in (0, 1, 2):
            raise ValueError('an open role must name a canonical row slot')
        elif (meaning.role_refs[role] is None or (role in forward_roles
              and meaning.role_refs[role][0] == 'ltm')):
            # A structural address to an anonymous constituent is still the
            # raw pending site. Its refined working read clears the forward
            # marker; an address alone does not assert a successful bind.
            result.append((kind, role))
    if (meaning.sentence_kind == 'relation' or
            (meaning.sentence_kind is None and int(meaning.role_mask.sum()) > 1)):
        for role in range(3):
            if (not bool(meaning.role_mask[role]) or
                    (meaning.role_refs[role] is None and
                     (meaning.sentence_kind == 'relation' or any(meaning.role_refs)))):
                result.append(('relation' if role == 1 else 'referent', role))
    return tuple(dict.fromkeys(result))


def needs_episode(meaning):
    """A region can need evidence without owning an extra operand slot."""
    return bool(open_slots(meaning)) or (meaning.mode == 'interrogative'
                                        and evidence_pair(meaning) == (0., 0.))


def conclude_exhausted(meaning):
    """A source-supported forward name becomes a provisional individual.

    This constructs only a trial-local constituent. The kept episode writes
    that individual through the ordinary LTM writer; a rejected trial has
    no durable allocation. A region without source evidence remains open.
    """
    if tuple(bindings(meaning).get('_source_evidence', evidence_pair(meaning))) == (0., 0.):
        return question(meaning, open_slots(meaning))
    from Meaning import ConceptualMeaning
    refs, children = list(meaning.role_refs), list(meaning.constituents)
    mask = meaning.role_mask.clone()
    data = bindings(meaning)
    records = data.get('_formation_records', ())
    filled = []
    for kind, role in open_slots(meaning):
        if kind != 'referent':
            continue
        provenance = tuple(record for record in records if dict(record).get('role') == role)
        child = with_slots(ConceptualMeaning.from_description(meaning.roles[role]), (),
                           pair=evidence_pair(meaning))
        child_data = bindings(child)
        child_data.update(_producing_operation='mint', _formation_records=provenance,
                          _formation_reason='search_exhausted')
        refs[role] = ('constituent', len(children))
        mask[role] = True
        children.append(replace(child, bindings=child_data))
        filled.append((kind, role))
    if filled:
        # Trial scoring precedes the kept write. The provisional individual
        # already fills this variable here, irrespective of its evidence.
        data['_bound_roles'] = tuple(dict.fromkeys((*data.get('_bound_roles', ()), *filled)))
    data['_forward_references'] = tuple(item for item in data.get('_forward_references', ())
                                         if refs[item[0]] is None)
    return with_slots(replace(meaning, role_refs=tuple(refs), role_mask=mask, bindings=data,
                             constituents=tuple(children)), open_slots(meaning))


def with_slots(meaning, slots, *, pair=None):
    data = bindings(meaning)
    data['_open_references'] = tuple(dict.fromkeys(slot for slot in slots if slot[0] != 'evidence'))
    if pair is not None:
        values = tuple(float(x) for x in pair)
        if len(values) != 2 or any(not 0 <= x <= 1 for x in values):
            raise ValueError('thought evidence requires two independent poles in [0,1]')
        data['_evidence_pair'] = values
    return replace(meaning, bindings=data)


def question(meaning, slots=None):
    """An interrogative region has free variables and no source evidence."""
    if slots is None:
        slots = open_slots(meaning)
    data = bindings(meaning)
    data['_source_evidence'] = (0., 0.)
    return with_slots(replace(meaning, mode='interrogative', bindings=data), slots, pair=(0., 0.))


def validate_local_references(meaning):
    """Check each meaning's local table before a filling can escape.

    Children own their own tables. Sharing a child is valid; a cycle, malformed
    address or out-of-range local address is a construction error.
    """
    seen, active = set(), set()

    def visit(value):
        if id(value) in active or len(active) > 64:
            raise ValueError('thought constituent cycle or depth limit at fill')
        if id(value) in seen:
            return
        active.add(id(value))

        def check(item):
            if isinstance(item, tuple):
                if item and item[0] == 'constituent':
                    if (len(item) != 2 or type(item[1]) is not int
                            or not 0 <= item[1] < len(value.constituents)):
                        raise ValueError('dangling or malformed local constituent reference at fill')
                else:
                    for part in item:
                        check(part)

        for item in value.metadata().values():
            check(item)
        for child in value.constituents:
            visit(child)
        active.remove(id(value))
        seen.add(id(value))

    visit(meaning)

